// TOPICALS SEAM — one place that groups lib/topicals-bank.ts into subjects
// and chapters for the public /topicals pages. Counts are computed from the
// bank at module scope; nothing is hardcoded and nothing is invented.
//
// The bank itself is generated by scripts/ingest-topicals.mjs (see its header
// for the honesty rules). This file never edits question text.

import { TOPICALS_BANK, type TopicalsQuestion } from './topicals-bank.ts';
import { FOUNDER_BANK } from './founder-bank.ts';
import { PIPELINE_BANK } from './pipeline-bank.ts';

// One source bank for the pages: the curated extraction, the founder's own papers and the
// import-ready rows of the question bank. Each row keeps its own source label.
const SOURCE_BANK: TopicalsQuestion[] = [...TOPICALS_BANK, ...FOUNDER_BANK, ...PIPELINE_BANK];

function normalizedOption(value: string | null | undefined): string {
  return typeof value === 'string' ? value.trim().replace(/\s+/g, ' ') : '';
}

// Do not serve an item with a blank option or repeated options. The November 2026
// founder-bank extraction contained OCR/parser failures that left answer choices
// inside the stem and one or more option fields empty. Seven curated rows also
// repeated an option. These items remain in their source files for correction,
// but cannot reach students until the source is fixed and the audit passes.
function hasFourDistinctOptions(question: TopicalsQuestion): boolean {
  const options = [
    question.option_a,
    question.option_b,
    question.option_c,
    question.option_d,
  ].map(normalizedOption);
  return options.every(Boolean) && new Set(options).size === 4;
}

const missingOptionRows = SOURCE_BANK.filter((question) =>
  [question.option_a, question.option_b, question.option_c, question.option_d]
    .some((option) => !normalizedOption(option))
).length;
const duplicateOptionRows = SOURCE_BANK.filter((question) => {
  const options = [
    question.option_a,
    question.option_b,
    question.option_c,
    question.option_d,
  ].map(normalizedOption);
  return options.every(Boolean) && new Set(options).size !== 4;
}).length;

export const TOPICALS_QUARANTINE_SUMMARY = {
  sourceRows: SOURCE_BANK.length,
  servedRows: SOURCE_BANK.filter(hasFourDistinctOptions).length,
  quarantinedRows: SOURCE_BANK.length - SOURCE_BANK.filter(hasFourDistinctOptions).length,
  missingOptionRows,
  duplicateOptionRows,
} as const;

const BANK: TopicalsQuestion[] = SOURCE_BANK.filter(hasFourDistinctOptions);

export type { TopicalsQuestion };

export function topicSlug(s: string): string {
  return s.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
}

export type TopicChapter = {
  /** URL-safe slug, e.g. "acellular-life". */
  slug: string;
  /** Display title, e.g. "Acellular Life". */
  title: string;
  count: number;
};

export type TopicSubject = {
  /** URL-safe slug, e.g. "biology". */
  slug: string;
  name: string;
  icon: string;
  count: number;
  /** Real syllabus chapters ("Respiration", "Waves"). */
  chapters: TopicChapter[];
  /**
   * Past-paper sets and mixed banks. They live in the same bank column as a
   * chapter but are not chapters — listing "Past Paper 2023" beside
   * "Respiration" told students the year was a syllabus topic.
   */
  sets: TopicChapter[];
};

/**
 * True for a bank entry that is a whole-paper set rather than a syllabus
 * chapter. The year in the name comes from the source extraction, not from a
 * verified sitting, so callers must not present these as official papers.
 */
export function isSetChapter(title: string): boolean {
  return (
    /^past\s*paper\b/i.test(title) ||
    /^(?:mixed|full)\s*bank$/i.test(title) ||
    /^mock\b/i.test(title) ||
    // A worksheet is a themed paper set, not a syllabus chapter.
    /^worksheet\b/i.test(title)
  );
}

/**
 * Two banks sometimes name the same chapter differently. Left alone, each spelling became its own
 * page, and two spellings that slug the same ("Work And Energy" / "Work and Energy") collided on one
 * URL, so the page showed only whichever was listed first and the rest of the questions were
 * unreachable. Chapters are therefore grouped by slug, and true synonyms are folded in here.
 */
const CHAPTER_ALIAS: Record<string, string> = {
  'Biology|Genetics': 'Inheritance',
};

/** The chapter name a question is served under, after synonyms are folded together. */
export function resolveChapter(subject: string, chapter: string): string {
  return CHAPTER_ALIAS[`${subject}|${chapter}`] ?? chapter;
}

function buildSubjects(): TopicSubject[] {
  // Every subject the bank actually carries is listed here. A subject missing from this list used to
  // mean its questions were ingested and then invisibly dropped at render time, so the ingest allow-list
  // in scripts/ingest-pipeline-bank.mjs must stay identical to this one.
  const order = [
    { name: 'Biology', icon: '🧬' },
    { name: 'Chemistry', icon: '⚗️' },
    { name: 'Physics', icon: '⚛️' },
    { name: 'English', icon: '📖' },
    { name: 'Mathematics', icon: '📐' },
    { name: 'Reasoning', icon: '🧩' },
  ];
  const subjects: TopicSubject[] = [];
  for (const s of order) {
    const rows = BANK.filter((q) => q.subject === s.name);
    // Keyed by slug, so "Work And Energy" and "Work and Energy" are one chapter, not two.
    const chapterMap = new Map<string, { title: string; count: number }>();
    for (const q of rows) {
      const title = resolveChapter(q.subject, q.chapter);
      const slug = topicSlug(title);
      const entry = chapterMap.get(slug);
      if (entry) entry.count += 1;
      else chapterMap.set(slug, { title, count: 1 });
    }
    const all: TopicChapter[] = [...chapterMap.entries()]
      .map(([slug, { title, count }]) => ({ slug, title, count }))
      .sort((a, b) => b.count - a.count || a.title.localeCompare(b.title));
    subjects.push({
      slug: topicSlug(s.name),
      name: s.name,
      icon: s.icon,
      count: rows.length,
      chapters: all.filter((c) => !isSetChapter(c.title)),
      sets: all.filter((c) => isSetChapter(c.title)),
    });
  }
  return subjects;
}

export const TOPICALS_SUBJECTS: TopicSubject[] = buildSubjects();

export const TOPICALS_TOTAL: number = BANK.length;

/** Real syllabus chapters only — past-paper sets are not chapters. */
export const TOPICALS_CHAPTER_COUNT: number = TOPICALS_SUBJECTS.reduce(
  (n, s) => n + s.chapters.length,
  0
);

/** Whole-paper sets (Past Paper <year>, Mixed Bank) across all subjects. */
export const TOPICALS_SET_COUNT: number = TOPICALS_SUBJECTS.reduce(
  (n, s) => n + s.sets.length,
  0
);

export function topicalSubject(slug: string): TopicSubject | null {
  return TOPICALS_SUBJECTS.find((s) => s.slug === slug) ?? null;
}

/** Chapter by subject+chapter slug; null for an unknown pair (caller 404s). */
export function topicalChapter(
  subjectSlug: string,
  chapterSlug: string
): { subject: TopicSubject; chapter: TopicChapter; questions: TopicalsQuestion[] } | null {
  const subject = topicalSubject(subjectSlug);
  if (!subject) return null;
  // Sets keep their existing URLs: /topicals/biology/past-paper-2023 resolves
  // whether it is listed as a chapter or as a set.
  const chapter =
    subject.chapters.find((c) => c.slug === chapterSlug) ??
    subject.sets.find((c) => c.slug === chapterSlug);
  if (!chapter) return null;
  // Compared by slug, not title: the two banks spell some chapters differently and the page must
  // hold every question filed under any spelling of that chapter.
  const questions = BANK.filter(
    (q) =>
      q.subject === subject.name &&
      topicSlug(resolveChapter(q.subject, q.chapter)) === chapter.slug
  );
  return { subject, chapter, questions };
}
